mapper.select:
SELECT  FROM requirement_doc_history
WHERE workspace_id = #{workspaceId} AND doc_id = #{docId}
ORDER BY version_no DESC

mapper.delete:
DELETE FROM requirement_doc_history
WHERE doc_id = #{docId}
  AND version_no <= (SELECT v FROM (
        SELECT MAX(version_no) AS v FROM requirement_doc_history WHERE doc_id = #{docId}
      ) t) - #{keep}

DELETE FROM requirement_doc_history
WHERE workspace_id = #{workspaceId}
  AND doc_id IN (SELECT id FROM requirement_doc WHERE workspace_id = #{workspaceId} AND req_id = #{reqId})
